import { useApp } from "../../context/AppContext";

export default function BankaHesabiSayfasi() {
  const { bankaHesabi, setBankaHesabi, paraCek, oturum } = useApp();

  const cekilecekTutar = bankaHesabi.bakiye;

  return (
    <div className="scroll-content">
      <div className="card" style={{ background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)", color: "#fff", padding: 24, marginBottom: 14 }}>
        <div style={{ fontSize: 14, opacity: 0.9, marginBottom: 8 }}>Cari Hesap Bakiyesi</div>
        <div style={{ fontSize: 36, fontWeight: 700, marginBottom: 8 }}>
          ₺{bankaHesabi.bakiye.toLocaleString()}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span>✓</span>
          <span style={{ fontSize: 13, opacity: 0.9 }}>Canlı güncel</span>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
          <div>
            <div style={{ fontSize: 14, color: "var(--text3)", marginBottom: 4 }}>Banka Hesabı</div>
            <div style={{ fontSize: 16, fontWeight: 700, color: "#3b82f6" }}>{bankaHesabi.adi}</div>
          </div>
          <button style={{ background: "var(--bg1)", border: "1px solid var(--border2)", borderRadius: "8px", padding: "8px 12px", fontSize: 13, cursor: "pointer" }}>✏️ Düzenle</button>
        </div>

        <div style={{ background: "var(--bg1)", padding: 16, borderRadius: "12px", marginBottom: 16 }}>
          <div style={{ fontSize: 12, color: "var(--text3)", marginBottom: 8 }}>IBAN</div>
          <div style={{ fontSize: 15, fontWeight: 600, fontFamily: "monospace", letterSpacing: 1 }}>{bankaHesabi.iban}</div>
        </div>

        <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
          <button onClick={() => setParaCekilecek(1000)} style={{ flex: 1, padding: "12px", background: "var(--bg2)", border: "1px solid var(--border2)", borderRadius: "12px", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
            ₺1.000
          </button>
          <button onClick={() => setParaCekilecek(5000)} style={{ flex: 1, padding: "12px", background: "var(--bg2)", border: "1px solid var(--border2)", borderRadius: "12px", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
            ₺5.000
          </button>
          <button onClick={() => setParaCekilecek(10000)} style={{ flex: 1, padding: "12px", background: "var(--bg2)", border: "1px solid var(--border2)", borderRadius: "12px", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
            ₺10.000
          </button>
        </div>
      </div>

      {paraCekilecek !== null && (
        <div className="card" style={{ marginBottom: 14, background: "var(--bg2)" }}>
          <div style={{ fontSize: 14, color: "var(--text3)", marginBottom: 8 }}>Para Çek</div>
          <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 16 }}>
            <input
              type="number"
              placeholder="Tutar gir..."
              style={{ flex: 1, padding: "12px", background: "var(--bg1)", border: "1px solid var(--border2)", borderRadius: "12px", fontSize: 16, outline: "none" }}
              value={paraCekilecek > 0 ? paraCekilecek.toLocaleString() : ""}
            />
            <span style={{ fontSize: 20, color: "var(--text2)" }}>₺</span>
          </div>

          <div style={{ display: "flex", gap: 8 }}>
            <button
              onClick={() => {
                const basarili = paraCek(paraCekilecek);
                if (basarili) {
                  alert(`₺${paraCekilecek.toLocaleString()} çekildi!`);
                  setParaCekilecek(null);
                } else {
                  alert("Yetersiz bakiye!");
                }
              }}
              className="btn btn-primary btn-full"
              style={{ padding: "14px" }}
            >
              Çek
            </button>
            <button onClick={() => setParaCekilecek(null)} style={{ flex: 1, padding: "14px", background: "var(--bg1)", border: "1px solid var(--border2)", borderRadius: "12px", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
              İptal
            </button>
          </div>
        </div>
      )}

      <div className="card">
        <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 12, letterSpacing: 1.5 }}>HAREKETLER</div>

        {[
          { t: "₺3.500", o: "Tedarikçi Ödemesi", s: "-", d: "12.05.2026" },
          { t: "+₺1.200", o: "Kamyoncu Ödemesi", s: "-", d: "11.05.2026" },
          { t: "-₺5.000", o: "Banka Havalesi", s: "-", d: "10.05.2026" },
          { t: "+₺2.800", o: "Tedarikçi Ödemesi", s: "-", d: "09.05.2026" },
          { t: "+₺1.500", o: "Kamyoncu Ödemesi", s: "-", d: "08.05.2026" },
        ].map((h, i) => (
          <div key={i} style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "14px",
            borderBottom: i < 4 ? "1px solid rgba(251,191,36,0.1)" : "none"
          }}>
            <div>
              <div style={{ fontSize: 14, fontWeight: 600, color: "var(--text)" }}>{h.o}</div>
              <div style={{ fontSize: 11, color: "var(--text3)" }}>Hesap: {oturum?.ad || "Demo"} • {h.s}</div>
            </div>
            <div style={{ fontSize: 16, fontWeight: 700, color: h.t.startsWith("+") ? "#10b981" : "#fbbf24" }}>
              {h.t}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
